const state={opening:'',detail:'',features:new Set(),location:new Set(),duration:'',pattern:new Set(),trigger:'',activity:'',trauma:'',redFlags:new Set(),wrist:'',step:0,ownedCold:false,noTopical:false,budget:false};
const intro=document.getElementById('intro'),chatView=document.getElementById('chatView'),solutionView=document.getElementById('solutionView'),conversation=document.getElementById('conversation'),interaction=document.getElementById('interaction'),prog=document.getElementById('prog');
const opening=document.getElementById('opening'),openingBtn=document.getElementById('openingBtn');
opening.addEventListener('input',()=>openingBtn.disabled=opening.value.trim().length<3);
openingBtn.addEventListener('click',()=>{state.opening=opening.value.trim();intro.classList.add('hidden');chatView.classList.remove('hidden');addUser(state.opening);setTimeout(()=>askDetail(),180)});
function addAI(html){const d=document.createElement('div');d.className='bubble ai';d.innerHTML='<b>Keneflex</b>'+html;conversation.appendChild(d);window.scrollTo({top:document.body.scrollHeight,behavior:'smooth'})}
function addUser(text){const d=document.createElement('div');d.className='bubble user';d.textContent=text;conversation.appendChild(d)}
function setProgress(n){prog.style.width=Math.max(8,Math.min(100,n))+'%'}
function textComposer(placeholder,buttonText,cb){interaction.innerHTML=`<textarea id="reply" placeholder="${placeholder}"></textarea><div class="row"><button id="send" class="primary">${buttonText}</button></div>`;document.getElementById('reply').focus();document.getElementById('send').onclick=()=>{const v=document.getElementById('reply').value.trim();if(!v)return;addUser(v);interaction.innerHTML='';cb(v)}}
function multiselect(title,hint,opts,nextLabel,cb){interaction.innerHTML=`<div class="selectHead">${title}</div><div class="selectHint">${hint}</div><div class="options" id="opts"></div><div class="row"><button id="nextMulti" class="primary">${nextLabel}</button></div>`;const box=document.getElementById('opts'),sel=new Set();opts.forEach(o=>{const b=document.createElement('button');b.className='opt'+(o.wide?' wide':'');b.innerHTML=o.label+(o.small?`<small>${o.small}</small>`:'');b.onclick=()=>{if(o.single){sel.clear();[...box.children].forEach(x=>x.classList.remove('on'))}else{opts.filter(x=>x.single).forEach(x=>{sel.delete(x.value);const idx=opts.indexOf(x);if(box.children[idx])box.children[idx].classList.remove('on')})}if(sel.has(o.value)){sel.delete(o.value);b.classList.remove('on')}else{sel.add(o.value);b.classList.add('on')}};box.appendChild(b)});document.getElementById('nextMulti').onclick=()=>{if(!sel.size)return;const labels=[...sel].map(v=>opts.find(o=>o.value===v)?.label.replace(/<[^>]*>/g,'')||v);addUser(labels.join(', '));interaction.innerHTML='';cb(sel)}}
function oneSelect(title,hint,opts,cb){interaction.innerHTML=`<div class="selectHead">${title}</div><div class="selectHint">${hint}</div><div class="options" id="one"></div>`;const box=document.getElementById('one');opts.forEach(o=>{const b=document.createElement('button');b.className='opt'+(o.wide?' wide':'');b.innerHTML=o.label+(o.small?`<small>${o.small}</small>`:'');b.onclick=()=>{addUser(o.label.replace(/<[^>]*>/g,''));interaction.innerHTML='';cb(o.value)};box.appendChild(b)})}
function parseDetail(t){const s=t.toLowerCase();if(/wrist/.test(s))state.location.add('wrist');if(/thumb/.test(s))state.location.add('thumb');if(/ache|aching|sore|soreness|pain/.test(s))state.features.add('pain');if(/rash|itch|red skin|skin change/.test(s))state.features.add('skin');if(/swell/.test(s))state.features.add('swelling');if(/numb|tingl|pins|needles/.test(s))state.features.add('neuro');if(/weak/.test(s))state.features.add('weakness');if(/pickle/.test(s))state.activity='pickleball';const m=s.match(/(\d+)\s*(day|days|week|weeks|month|months)/);if(m)state.duration=m[1]+' '+m[2];if(/grip|twist|jar/.test(s))state.trigger=t;}
function askDetail(){setProgress(17);addAI(`Tell me about that—what’s been going on? <span class="micro">Don’t worry about using medical terms.</span>`);textComposer('For example: It has been sore for a few weeks and gets worse when I use it…','Continue →',v=>{state.detail=v;parseDetail(v);askBroad()})}
function askBroad(){setProgress(29);addAI(`Thanks. Before I assume this is a muscle-or-joint problem, I want to make sure I’m not missing another kind of hand problem.`);multiselect('What else are you noticing?','Pick every one that applies. If none fit, choose “something else” or “not sure.”',[{value:'pain',label:'Pain / soreness'},{value:'swelling',label:'Swelling'},{value:'stiff',label:'Stiffness'},{value:'neuro',label:'Numbness / tingling'},{value:'weakness',label:'Weakness'},{value:'skin',label:'Rash / redness / skin change'},{value:'wound',label:'Cut / wound / burn'},{value:'color',label:'Color or temperature change'},{value:'other',label:'Something else'},{value:'unsure',label:'I’m not sure'}],'That’s what I’m noticing →',sel=>{sel.forEach(x=>state.features.add(x));if(sel.has('skin')||sel.has('wound')||sel.has('color'))addAI(`That extra detail matters. In a real Keneflex conversation, I’d branch into skin, wound, or circulation questions before recommending a muscle-or-joint product. For this standardized prototype, keep answering the scenario facts so I can test the conservative hand-pain path.`);askLocation()})}
function askLocation(){setProgress(39);if(state.location.size)addAI(`You mentioned the ${[...state.location].join(' and ')} area. I want to make sure I have the location right.`);else addAI(`Let’s narrow down where it’s bothering you most.`);multiselect('Where do you feel it?','Pick all that apply.',[{value:'thumb',label:'Thumb / base of thumb'},{value:'fingers',label:'Fingers'},{value:'palm',label:'Palm'},{value:'back',label:'Back of hand'},{value:'wrist',label:'Wrist'},{value:'pinky',label:'Pinky-side of hand/wrist'},{value:'diffuse',label:'Several areas / hard to pinpoint'}],'Continue →',sel=>{state.location=sel;askOnset()})}
function askOnset(){setProgress(49);addAI(`One thing that changes what I’d be comfortable suggesting is whether this followed an injury or came on more gradually.`);oneSelect('How did it start?','Choose the closest answer.',[{value:'gradual',label:'It came on gradually / I’m not sure exactly when'},{value:'activity',label:'I noticed it after repeated use or activity'},{value:'trauma',label:'After a fall, hit, twist, or other injury'}],v=>{state.trauma=v;if(v==='trauma')askSafety();else askDuration()})}
function askSafety(){setProgress(56);addAI(`Because there was an injury, I’d check a few warning signs before talking products.`);multiselect('Any of these now?','Pick all that apply.',[{value:'deformity',label:'Looks crooked or deformed'},{value:'move',label:'Can’t move it normally'},{value:'numb',label:'Persistent numbness'},{value:'weak',label:'Marked weakness'},{value:'wound',label:'Open wound'},{value:'none',label:'None of these',wide:true,single:true}],'Continue →',sel=>{state.redFlags=sel;if(!sel.has('none'))stopForCare();else askDuration()})}
function askDuration(){setProgress(59);if(state.duration){addAI(`You said this has been going on for ${state.duration}. I also want to know the pattern—when it shows up can be as useful as how long it’s been there.`);askPattern()}else{addAI(`How long it’s been there helps, but I won’t stop at duration—I’ll also ask when you notice it most.`);oneSelect('How long has this been going on?','Closest answer is fine.',[{value:'days',label:'A few days or less'},{value:'1-2w',label:'About 1–2 weeks'},{value:'3w',label:'About 3 weeks'},{value:'month',label:'More than a month'},{value:'unsure',label:'I’m not sure'}],v=>{state.duration=v;askPattern()})}}
function askPattern(){setProgress(67);multiselect('When do you notice it most?','Pick all that apply. This helps me distinguish different patterns rather than treating every “hand pain” the same.',[{value:'use',label:'While I’m using my hand'},{value:'after',label:'After activity / later that day'},{value:'morning',label:'First thing in the morning'},{value:'night',label:'At night'},{value:'wake',label:'It wakes me up'},{value:'constant',label:'Pretty much all the time'},{value:'intermittent',label:'It comes and goes'},{value:'unsure',label:'I haven’t noticed a pattern'}],'Continue →',sel=>{state.pattern=sel;askTrigger()})}
function askTrigger(){setProgress(74);if(state.trigger){addAI(`You already told me some of what aggravates it, so I won’t make you repeat yourself. What, if anything, makes it feel better?`);textComposer('Rest, ice, changing position, nothing I’ve noticed…','Continue →',v=>{state.relief=v;askGoal()})}else{addAI(`What tends to bring it on or make it worse?`);textComposer('Gripping, twisting, typing, lifting, sleeping on it…','Continue →',v=>{state.trigger=v;askGoal()})}}
function askGoal(){setProgress(81);if(state.activity){addAI(`You mentioned ${state.activity}. I care more about what you’re trying to keep doing than asking you to choose how much “restriction” you think you need.`);state.goal='keep '+state.activity;askSafetyBroad()}else{addAI(`What are you trying to keep doing—or get back to doing—without this getting in the way?`);textComposer('Work, sleep, pickleball, opening jars, lifting, exercise…','Continue →',v=>{state.activity=v;state.goal=v;askSafetyBroad()})}}
function askSafetyBroad(){setProgress(88);addAI(`I’m close. I just want to make sure there isn’t anything here that would make self-care the wrong next step.`);multiselect('Have you had any of these?','Pick all that apply.',[{value:'numb',label:'New or persistent numbness / tingling'},{value:'weak',label:'Marked weakness or dropping things'},{value:'majorSwelling',label:'Major or rapidly increasing swelling'},{value:'fever',label:'Fever or feeling significantly unwell'},{value:'deformity',label:'Obvious deformity'},{value:'open',label:'Open wound / significant skin problem'},{value:'none',label:'None of these',wide:true,single:true}],'Continue →',sel=>{state.redFlags=sel;if(!sel.has('none'))stopForCare();else askFit()})}
function askFit(){setProgress(94);addAI(`Based on the pattern so far, I’m comfortable considering a conservative wrist/thumb-support plan. To choose a specific support, I need one fit detail.`);textComposer('Enter wrist circumference in inches (for the test, 7.0)','Use this measurement →',v=>{state.wrist=v||'7.0';showEnough()})}
function stopForCare(){setProgress(100);addAI(`<strong>I wouldn’t jump to a store product yet.</strong> One of the things you selected can change the safest next step. In a production Keneflex experience I’d clarify that finding and, when appropriate, recommend professional evaluation instead of forcing an OTC recommendation.`);interaction.innerHTML='<div class="notice warn">This branch intentionally stops commerce. Safety wins over completing the test path.</div>'}
function showEnough(){setProgress(100);addAI(`Okay—I think I have enough to tell you where I’d start.`);const summary=document.createElement('div');summary.className='card enough';summary.style.marginTop='12px';summary.innerHTML=`<h2>Here’s the picture I’m working with.</h2><p>This is mainly a ${[...state.location].join(' + ')} problem, it has a use-related pattern, you want to keep doing ${state.activity||'your normal activity'}, and you haven’t described the warning signs that would make me stop self-care. I’m going to favor support and recovery without more motion restriction than the situation appears to need.</p><div class="row"><button id="seePlan" class="primary">Show me what you’d do →</button></div>`;interaction.replaceWith(summary);document.getElementById('seePlan').onclick=showSolution}
function showSolution(){chatView.classList.add('hidden');solutionView.classList.remove('hidden');renderWhy();window.scrollTo(0,0)}
function renderWhy(){const rows=document.getElementById('whyRows');const location=[...state.location].join(' + ')||'wrist/thumb area';const activity=state.activity||'your activity';const pattern=[...state.pattern].join(', ')||'with use';const wrist=state.wrist||'7.0';rows.innerHTML=`<div class="whyrow"><div class="whyIn"><b>You told me</b>${location}, mainly aggravated by ${state.trigger||'gripping/twisting'}.</div><div class="arrow">→</div><div class="whyOut"><b>Why that matters</b>I looked for a support that covers the irritated area rather than a generic wrist-only option.</div></div><div class="whyrow"><div class="whyIn"><b>You want to keep doing</b>${activity}.</div><div class="arrow">→</div><div class="whyOut"><b>Why that matters</b>I ruled out more rigid options that would limit more useful motion than your current pattern appears to require.</div></div><div class="whyrow"><div class="whyIn"><b>The timing pattern</b>${pattern}.</div><div class="arrow">→</div><div class="whyOut"><b>Why that matters</b>That supports pairing the brace with load changes and after-activity recovery instead of treating the product as the whole solution.</div></div><div class="whyrow"><div class="whyIn"><b>Your fit</b>${wrist}-inch wrist.</div><div class="arrow">→</div><div class="whyOut"><b>Why that matters</b>Medium is the fit I’d use for the support shown in this prototype.</div></div>`}
function tune(kind){const r=document.getElementById('tuneResult');r.classList.remove('hidden');if(kind==='cold'){state.ownedCold=true;r.innerHTML='<b>Use yours.</b> If your cold pack is intact, clean, comfortable and works for the intended recovery role, I would not sell you another one. Your revised product total is <b>$31.98</b>.';document.getElementById('total').textContent='$31.98'}if(kind==='topical'){state.noTopical=true;r.innerHTML='<b>Remove the topical.</b> It is supportive, not essential. The brace + recovery + self-care plan remains coherent. Revised total: <b>$40.99</b>.';document.getElementById('total').textContent='$40.99'}if(kind==='budget'){state.budget=true;r.innerHTML='<b>I would protect the core plan before chasing the lowest price.</b> First remove the optional topical. If you already have an adequate cold option, use it. That brings the spend to <b>$19.99</b> without substituting a poorer-fitting primary support.';document.getElementById('total').textContent='$19.99'}}
document.querySelectorAll('[data-tune]').forEach(b=>b.addEventListener('click',()=>tune(b.dataset.tune)));
const modal=document.getElementById('modal'),modalContent=document.getElementById('modalContent');const modalCopy={how:`<h2>How Keneflex works</h2><h3>1. Talk normally</h3><p>Start with whatever you know. You do not need the diagnosis, the right anatomy word, or a product in mind.</p><h3>2. I figure out what matters</h3><p>Keneflex listens to what you already said, thinks broadly about the kinds of problems that could fit, and asks only the follow-up questions that can change safety or the solution.</p><h3>3. I do the homework</h3><p>The intended production system combines clinical knowledge, conservative-care options, product evidence, expert practice, real-world success/failure patterns and Keneflex outcome data.</p><h3>4. I build the best complete plan</h3><p>That may include products, home care, behavior changes—or a recommendation not to buy something. Budget and preferences can adjust the plan afterward.</p><h3>5. We learn from what happens</h3><p>If the plan works, great. If not, Keneflex should reconsider the problem rather than blindly escalate products.</p>`,approach:`<h2>Our approach</h2><h3>Start with the problem, not the shelf.</h3><p>We are trying to remove decision work, not give you another catalog.</p><h3>Think broadly before narrowing.</h3><p>“My hand hurts” does not automatically mean a brace. Keneflex should consider other relevant problem types and know when self-care is not the right next step.</p><h3>Recommend what we would recommend to someone we care about.</h3><p>The default is the best coherent solution—not the smallest cart and not the largest cart.</p><h3>Evidence matters, but so does real-world experience.</h3><p>Strong evidence, conservative practice, expert observations and anecdotal patterns can all inform the search, but they should not be treated as equally certain.</p><h3>Commercial economics come after suitability.</h3><p>Keneflex may eventually earn money from purchases. That cannot make an option eligible or change which option wins.</p>`};document.querySelectorAll('[data-modal]').forEach(b=>b.onclick=()=>{modalContent.innerHTML=modalCopy[b.dataset.modal];modal.classList.remove('hidden')});document.getElementById('closeModal').onclick=()=>modal.classList.add('hidden');modal.addEventListener('click',e=>{if(e.target===modal)modal.classList.add('hidden')});